local t = {
	Name = "Valve",
	PointCost = 150,
	DandyStoreItem = true,
	FloorItem = false,
	Rarity = "UltraRare",
	Icon = "rbxassetid://18583522993",
	Description = "Use this item while Extracting a Machine to instantly complete it.",
	ItemAmount = 999
}

game:GetService("Debris")

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local SoundUtils = require(ReplicatedStorage.Modules.Audio.SoundUtils)

function t.UseItem(p1, p2) --[[ UseItem | Line: 17 | Upvalues: t (copy), SoundUtils (copy) ]]
	local Stats = p1:WaitForChild("Stats")

	Stats:WaitForChild("CurrentStamina")
	Stats:WaitForChild("Stamina")
	p1:WaitForChild("Humanoid")

	local Decoding = p1:WaitForChild("Decoding")

	Stats:WaitForChild("DecodeSpeedModifier")
	Stats:WaitForChild("RunSpeed")
	Stats:WaitForChild("WalkSpeed")

	if Decoding.Value == nil then
		return {
			Outcome = false,
			Reason = "Item can only be used while extracting a Machine!"
		}
	end

	local t2 = {
		Outcome = true,
		Reason = "Can\'t use that item at full Stamina!"
	}

	if p1:FindFirstChild("HumanoidRootPart") then
		local Stats2 = Decoding.Value:WaitForChild("Stats")
		local CurrentAmount = Stats2:WaitForChild("CurrentAmount")
		local RequiredAmount = Stats2:WaitForChild("RequiredAmount")
		local PlayerCompletion = Decoding.Value:WaitForChild("PlayerCompletion")
		local v1 = PlayerCompletion:FindFirstChild(p1.Name)

		CurrentAmount.Value = CurrentAmount.Value + t.ItemAmount

		if v1 then
			v1.Value = v1.Value + t.ItemAmount
		else
			local v2 = Instance.new("NumberValue")

			v2.Name = p1.Name
			v2.Value = t.ItemAmount
			v2.Parent = PlayerCompletion
		end

		if CurrentAmount.Value >= RequiredAmount.Value then
			CurrentAmount.Value = RequiredAmount.Value
		end

		local HumanoidRootPart = p1:WaitForChild("HumanoidRootPart")
		local v3 = script.UseSound:Clone()

		v3.Parent = HumanoidRootPart
		v3:Play()
		SoundUtils.SafeCleanup(v3)
	end

	p2.Value = "None"

	local v4 = workspace.Info.PlayerStats:FindFirstChild(p1.Name)

	if not v4 then
		return t2
	end

	local SurvivalPoints = v4:WaitForChild("SurvivalPoints")

	SurvivalPoints.Value = SurvivalPoints.Value + 10

	return t2
end

return t